/* ============================================================
   WellStream Platform — Design System
   ============================================================ */

/* ── 0. Tokens (Primitive + Semantic) ─────────────────────── */
:root {
  /* Primitive Colors — OKLCH */
  --color-navy-50:  oklch(96%  0.01  260);
  --color-navy-100: oklch(90%  0.02  260);
  --color-navy-200: oklch(80%  0.04  260);
  --color-navy-300: oklch(65%  0.08  260);
  --color-navy-400: oklch(50%  0.12  260);
  --color-navy-500: oklch(35%  0.14  260);
  --color-navy-600: oklch(25%  0.12  260);
  --color-navy-700: oklch(18%  0.10  260);
  --color-navy-800: oklch(12%  0.08  260);
  --color-navy-900: oklch(8%   0.06  260);

  --color-teal-300: oklch(78% 0.14 195);
  --color-teal-400: oklch(68% 0.16 195);
  --color-teal-500: oklch(58% 0.18 195);
  --color-teal-600: oklch(48% 0.16 195);

  --color-green-400: oklch(72% 0.20 145);
  --color-green-500: oklch(62% 0.22 145);

  --color-white: oklch(100% 0 0);
  --color-gray-50:  oklch(97% 0.01 260);
  --color-gray-100: oklch(92% 0.02 260);
  --color-gray-200: oklch(82% 0.03 260);
  --color-gray-300: oklch(70% 0.04 260);
  --color-gray-400: oklch(58% 0.05 260);
  --color-gray-500: oklch(46% 0.05 260);
  --color-gray-600: oklch(36% 0.04 260);
  --color-gray-700: oklch(26% 0.03 260);
  --color-gray-800: oklch(16% 0.02 260);
  --color-gray-900: oklch(10% 0.01 260);

  /* Semantic Colors */
  --bg-page:        var(--color-navy-900);
  --bg-surface:     var(--color-navy-800);
  --bg-surface-2:   var(--color-navy-700);
  --bg-card:        var(--color-navy-800);
  --bg-elevated:    var(--color-navy-700);
  --bg-header:      oklch(8% 0.06 260 / 0.92);

  --text-primary:   var(--color-white);
  --text-secondary: var(--color-gray-200);
  --text-muted:     var(--color-gray-400);
  --text-inverse:   var(--color-navy-900);

  --accent-primary:   var(--color-teal-400);
  --accent-secondary: var(--color-green-500);
  --accent-hover:     var(--color-teal-300);

  --border-subtle:    oklch(20% 0.04 260);
  --border-default:   oklch(30% 0.06 260);
  --border-focus:     var(--accent-primary);

  /* Spacing Scale (8px base) */
  --space-1: 0.25rem;   /* 4px  */
  --space-2: 0.5rem;    /* 8px  */
  --space-3: 0.75rem;   /* 12px */
  --space-4: 1rem;      /* 16px */
  --space-5: 1.25rem;   /* 20px */
  --space-6: 1.5rem;    /* 24px */
  --space-8: 2rem;      /* 32px */
  --space-10: 2.5rem;   /* 40px */
  --space-12: 3rem;     /* 48px */
  --space-16: 4rem;     /* 64px */
  --space-20: 5rem;     /* 80px */
  --space-24: 6rem;     /* 96px */

  /* Typography */
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", ui-monospace, monospace;

  --text-xs:   clamp(0.6875rem, 0.65rem + 0.15vw, 0.75rem);
  --text-sm:   clamp(0.8125rem, 0.78rem + 0.15vw, 0.875rem);
  --text-base: clamp(0.9375rem, 0.9rem + 0.2vw, 1rem);
  --text-lg:   clamp(1.0625rem, 1rem + 0.3vw, 1.125rem);
  --text-xl:   clamp(1.25rem,  1.1rem + 0.5vw, 1.5rem);
  --text-2xl:  clamp(1.5rem,  1.2rem + 1vw,   2rem);
  --text-3xl:  clamp(1.875rem,1.4rem + 1.5vw, 2.5rem);
  --text-4xl:  clamp(2.25rem, 1.6rem + 2.5vw, 3.5rem);
  --text-5xl:  clamp(2.75rem, 1.8rem + 3.5vw, 5rem);

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.5);
  --shadow-glow: 0 0 20px oklch(68% 0.16 195 / 0.25);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --container-max: 1280px;
  --header-height: 4rem;
}

/* ── 1. Reset & Base ──────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-page);
  min-height: 100vh;
}
img, picture, video, canvas, svg { display: block; max-width: 100%; }
input, button, textarea, select { font: inherit; color: inherit; }
button { cursor: pointer; background: none; border: none; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }

/* ── 2. Utilities ─────────────────────────────────────────── */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--space-6);
}
@media (max-width: 640px) {
  .container { padding-inline: var(--space-4); }
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* ── 3. Components ────────────────────────────────────────── */

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  white-space: nowrap;
}
.btn--primary {
  background: var(--accent-primary);
  color: var(--color-navy-900);
}
.btn--primary:hover {
  background: var(--accent-hover);
  box-shadow: var(--shadow-glow);
  transform: translateY(-1px);
}
.btn--secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}
.btn--secondary:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
  background: oklch(68% 0.16 195 / 0.08);
}
.btn--outline-light {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--text-primary);
}
.btn--outline-light:hover {
  background: var(--text-primary);
  color: var(--color-navy-900);
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  transition: border-color var(--transition-base), transform var(--transition-base), box-shadow var(--transition-base);
}
.card:hover {
  border-color: var(--border-default);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

/* Section header */
.section-label {
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-primary);
  margin-bottom: var(--space-3);
}
.section-title {
  font-size: var(--text-3xl);
  font-weight: 700;
  line-height: 1.15;
  color: var(--text-primary);
  margin-bottom: var(--space-4);
}
.section-desc {
  font-size: var(--text-lg);
  color: var(--text-secondary);
  line-height: 1.6;
  max-width: 60ch;
}

/* ── 4. Header & Navigation ───────────────────────────────── */
.header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 100;
  height: var(--header-height);
  background: var(--bg-header);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}
.header__logo {
  font-size: var(--text-xl);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}
.header__logo span { color: var(--accent-primary); }

.nav { display: flex; align-items: center; gap: var(--space-8); }
.nav__links { display: flex; align-items: center; gap: var(--space-6); }
.nav__link {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}
.nav__link:hover, .nav__link[aria-current="page"] { color: var(--text-primary); }
.nav__link[aria-current="page"]::after {
  content: "";
  position: absolute;
  bottom: -4px; left: 0; right: 0;
  height: 2px;
  background: var(--accent-primary);
  border-radius: var(--radius-full);
}

/* Dropdown */
.dropdown { position: relative; }
.dropdown__trigger {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: color var(--transition-fast);
}
.dropdown__trigger:hover { color: var(--text-primary); }
.dropdown__trigger svg { transition: transform var(--transition-fast); }
.dropdown[open] .dropdown__trigger svg { transform: rotate(180deg); }
.dropdown__menu {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: 0;
  min-width: 220px;
  background: var(--bg-surface-2);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-2);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transform: translateY(-4px);
  pointer-events: none;
  transition: opacity var(--transition-fast), transform var(--transition-fast);
}
.dropdown[open] .dropdown__menu {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}
.dropdown__item {
  display: block;
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast), color var(--transition-fast);
}
.dropdown__item:hover {
  background: oklch(25% 0.08 260);
  color: var(--text-primary);
}

/* Mobile nav toggle */
.nav__toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}
.nav__toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

@media (max-width: 900px) {
  .nav__toggle { display: flex; }
  .nav__links {
    position: fixed;
    inset: var(--header-height) 0 auto 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    background: var(--bg-surface);
    border-bottom: 1px solid var(--border-subtle);
    padding: var(--space-4);
    transform: translateY(-100%);
    opacity: 0;
    pointer-events: none;
    transition: all var(--transition-base);
  }
  .nav__links.is-open {
    transform: translateY(0);
    opacity: 1;
    pointer-events: auto;
  }
  .nav__link {
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-md);
  }
  .nav__link:hover { background: var(--bg-surface-2); }
  .dropdown__menu {
    position: static;
    opacity: 1;
    transform: none;
    pointer-events: auto;
    box-shadow: none;
    background: var(--bg-surface);
    border: none;
    padding-left: var(--space-4);
    display: none;
  }
  .dropdown.is-open .dropdown__menu { display: block; }
}

/* ── 5. Footer ────────────────────────────────────────────── */
.footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  padding-block: var(--space-16) var(--space-8);
}
.footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
}
@media (max-width: 900px) {
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .footer__grid { grid-template-columns: 1fr; }
}
.footer__col h4 {
  font-size: var(--text-sm);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-primary);
  margin-bottom: var(--space-4);
}
.footer__col a {
  display: block;
  font-size: var(--text-sm);
  color: var(--text-muted);
  padding-block: var(--space-1);
  transition: color var(--transition-fast);
}
.footer__col a:hover { color: var(--accent-primary); }
.footer__bottom {
  margin-top: var(--space-12);
  padding-top: var(--space-6);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
}
.footer__brand {
  font-size: var(--text-lg);
  font-weight: 800;
  color: var(--text-primary);
}
.footer__brand span { color: var(--accent-primary); }
.footer__copy {
  font-size: var(--text-xs);
  color: var(--text-muted);
}

/* ── 6. Tabs ──────────────────────────────────────────────── */
.tabs {}
.tabs__list {
  display: flex;
  gap: var(--space-1);
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: var(--space-6);
  overflow-x: auto;
}
.tabs__btn {
  padding: var(--space-3) var(--space-5);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  white-space: nowrap;
  transition: color var(--transition-fast), border-color var(--transition-fast);
}
.tabs__btn:hover { color: var(--text-secondary); }
.tabs__btn[aria-selected="true"] {
  color: var(--accent-primary);
  border-color: var(--accent-primary);
}
.tabs__panel { display: none; }
.tabs__panel.is-active { display: block; animation: fadeIn 300ms ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

/* ── 7. Accordion ─────────────────────────────────────────── */
.accordion {}
.accordion__item {
  border-bottom: 1px solid var(--border-subtle);
}
.accordion__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-5) 0;
  font-size: var(--text-lg);
  font-weight: 600;
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
  transition: color var(--transition-fast);
}
.accordion__header:hover { color: var(--accent-primary); }
.accordion__icon {
  width: 20px; height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
}
.accordion__item.is-open .accordion__icon { transform: rotate(180deg); }
.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}
.accordion__item.is-open .accordion__body {
  max-height: 500px;
  padding-bottom: var(--space-5);
}
.accordion__body p {
  font-size: var(--text-base);
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ── 8. Forms ─────────────────────────────────────────────── */
.form-group { margin-bottom: var(--space-5); }
.form-label {
  display: block;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: var(--space-2);
}
.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-base);
  color: var(--text-primary);
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}
.form-input::placeholder,
.form-textarea::placeholder { color: var(--text-muted); }
.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px oklch(68% 0.16 195 / 0.15);
}
.form-input:invalid:not(:placeholder-shown) { border-color: oklch(60% 0.2 25); }
.form-textarea { min-height: 120px; resize: vertical; }
.form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-5);
}
@media (max-width: 640px) {
  .form-grid { grid-template-columns: 1fr; }
}

/* ── 9. Cookie Banner ─────────────────────────────────────── */
.cookie-banner {
  position: fixed;
  inset: auto 0 0 0;
  z-index: 200;
  background: var(--bg-surface-2);
  border-top: 1px solid var(--border-default);
  padding: var(--space-4) 0;
  transform: translateY(100%);
  transition: transform var(--transition-slow);
}
.cookie-banner.is-visible { transform: translateY(0); }
.cookie-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  flex-wrap: wrap;
}
.cookie-banner__text {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  max-width: 70ch;
}
.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

/* ── 10. Progress Bar ─────────────────────────────────────── */
.progress-bar {
  height: 8px;
  background: var(--bg-surface-2);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.progress-bar__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-primary), var(--accent-secondary));
  border-radius: var(--radius-full);
  transition: width 1s ease;
}

/* ── 11. Stat Circle ──────────────────────────────────────── */
.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--space-2);
}
.stat-circle__ring {
  width: 140px; height: 140px;
  border-radius: 50%;
  background: conic-gradient(var(--accent-primary) var(--pct), var(--bg-surface-2) 0);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.stat-circle__ring::before {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: var(--bg-page);
}
.stat-circle__value {
  position: relative;
  font-size: var(--text-2xl);
  font-weight: 800;
  color: var(--text-primary);
}
.stat-circle__label {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  max-width: 16ch;
}

/* ── 12. Testimonial Carousel ─────────────────────────────── */
.carousel { position: relative; }
.carousel__track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.carousel__track::-webkit-scrollbar { display: none; }
.carousel__slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}
@media (min-width: 768px) {
  .carousel__slide { flex: 0 0 calc(50% - var(--space-3)); }
}
.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-6);
}
.carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--border-default);
  transition: background var(--transition-fast), transform var(--transition-fast);
}
.carousel__dot.is-active {
  background: var(--accent-primary);
  transform: scale(1.2);
}

/* ── 13. Hero Pattern ─────────────────────────────────────── */
.hero {
  position: relative;
  padding-block: calc(var(--header-height) + var(--space-20)) var(--space-20);
  overflow: hidden;
}
.hero__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 20% 40%, oklch(25% 0.12 260 / 0.5) 0%, transparent 60%),
    radial-gradient(ellipse 60% 50% at 80% 60%, oklch(48% 0.16 195 / 0.15) 0%, transparent 50%),
    var(--bg-page);
  z-index: 0;
}
.hero__content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}
.hero__label {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-primary);
  background: oklch(68% 0.16 195 / 0.1);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-5);
}
.hero__title {
  font-size: var(--text-5xl);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: var(--space-5);
}
.hero__subtitle {
  font-size: var(--text-xl);
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: var(--space-8);
  max-width: 60ch;
}
.hero__actions {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

/* ── 14. Diagrams ─────────────────────────────────────────── */
.diagram-pillars {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}
.diagram-pillar {
  flex: 1 1 280px;
  max-width: 340px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  position: relative;
  transition: border-color var(--transition-base), transform var(--transition-base);
}
.diagram-pillar:hover {
  border-color: var(--accent-primary);
  transform: translateY(-4px);
}
.diagram-pillar__icon {
  width: 56px; height: 56px;
  margin-inline: auto;
  margin-bottom: var(--space-4);
  background: oklch(68% 0.16 195 / 0.12);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
}
.diagram-pillar__icon svg {
  width: 28px; height: 28px;
  color: var(--accent-primary);
}
.diagram-pillar__title {
  font-size: var(--text-xl);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: var(--space-2);
}
.diagram-pillar__desc {
  font-size: var(--text-base);
  color: var(--text-secondary);
  line-height: 1.6;
}
.diagram-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-primary);
  font-size: var(--text-2xl);
  font-weight: 300;
}
@media (max-width: 768px) {
  .diagram-connector { display: none; }
}

/* Lifecycle diagram */
.lifecycle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  flex-wrap: wrap;
}
.lifecycle__stage {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-4) var(--space-5);
  text-align: center;
  min-width: 120px;
  transition: border-color var(--transition-base);
}
.lifecycle__stage:hover { border-color: var(--accent-primary); }
.lifecycle__stage-title {
  font-size: var(--text-sm);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: var(--space-1);
}
.lifecycle__stage-desc {
  font-size: var(--text-xs);
  color: var(--text-muted);
}
.lifecycle__arrow {
  color: var(--accent-primary);
  flex-shrink: 0;
}
@media (max-width: 640px) {
  .lifecycle__arrow { transform: rotate(90deg); }
}

/* ── 15. Misc ─────────────────────────────────────────────── */
.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--space-5);
}
.feature-list__item {
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
}
.feature-list__icon {
  width: 40px; height: 40px;
  flex-shrink: 0;
  background: oklch(68% 0.16 195 / 0.1);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-primary);
}
.feature-list__content h4 {
  font-size: var(--text-base);
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: var(--space-1);
}
.feature-list__content p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Check list */
.check-list { display: flex; flex-direction: column; gap: var(--space-4); }
.check-list__item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
}
.check-list__icon {
  width: 24px; height: 24px;
  flex-shrink: 0;
  color: var(--accent-secondary);
  margin-top: 2px;
}
.check-list__text {
  font-size: var(--text-base);
  color: var(--text-secondary);
  line-height: 1.5;
}
.check-list__text strong {
  color: var(--text-primary);
  font-weight: 600;
}

/* Timeline */
.timeline { display: flex; flex-direction: column; gap: var(--space-6); }
.timeline__item {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: var(--space-6);
  align-items: center;
}
@media (max-width: 640px) {
  .timeline__item { grid-template-columns: 1fr; gap: var(--space-3); }
}
.timeline__badge {
  font-size: var(--text-sm);
  font-weight: 700;
  color: var(--accent-primary);
  background: oklch(68% 0.16 195 / 0.1);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  text-align: center;
  white-space: nowrap;
}
.timeline__content h4 {
  font-size: var(--text-base);
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: var(--space-1);
}
.timeline__content p {
  font-size: var(--text-sm);
  color: var(--text-secondary);
}
.timeline__bar { margin-top: var(--space-3); }

/* Testimonial card */
.testimonial {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
}
.testimonial__quote {
  font-size: var(--text-lg);
  font-style: italic;
  color: var(--text-primary);
  line-height: 1.6;
  margin-bottom: var(--space-5);
}
.testimonial__author {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--text-secondary);
}
.testimonial__author span { color: var(--text-muted); font-weight: 400; }

/* Banner */
.banner {
  background: linear-gradient(135deg, var(--bg-surface), var(--bg-surface-2));
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: var(--space-8) var(--space-10);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  flex-wrap: wrap;
}
.banner__content h3 {
  font-size: var(--text-2xl);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: var(--space-1);
}
.banner__content p {
  font-size: var(--text-base);
  color: var(--text-secondary);
}

/* Grid cards */
.grid-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-5);
}

/* Section padding */
.section { padding-block: var(--space-20); }
.section--tight { padding-block: var(--space-12); }

/* Background variants */
.bg-surface { background: var(--bg-surface); }
